export type Section={y:number;rx:number;rz:number;x?:number;z?:number};
export type Surface={positions:number[];indices:number[]};

/** Closed custom surfaces. Coordinates are authoring units, Y up, +Z forward. */
export function loftSurface(sections:readonly Section[],segments=24,square=1):Surface{
  if(sections.length<2||segments<3||!Number.isInteger(segments)||!Number.isFinite(square)||square<=0)throw Error('Invalid loft resolution');
  const rings=[...sections].sort((a,b)=>a.y-b.y);
  if(rings.some((s,i)=>![s.y,s.rx,s.rz,s.x??0,s.z??0].every(Number.isFinite)||s.rx<=0||s.rz<=0||(i>0&&s.y===rings[i-1].y)))throw Error('Invalid loft section');
  const positions:number[]=[],indices:number[]=[];
  for(const s of rings)for(let j=0;j<segments;j++){
    const a=j/segments*Math.PI*2,c=Math.cos(a),t=Math.sin(a);
    positions.push((s.x??0)+Math.sign(c)*Math.abs(c)**square*s.rx,s.y,(s.z??0)+Math.sign(t)*Math.abs(t)**square*s.rz);
  }
  for(let i=0;i<rings.length-1;i++)for(let j=0;j<segments;j++){
    const a=i*segments+j,b=a+segments,n=i*segments+(j+1)%segments,m=n+segments;
    indices.push(a,b,n,n,b,m);
  }
  for(const [i,top] of [[0,false],[rings.length-1,true]] as const){
    const s=rings[i],center=positions.length/3;positions.push(s.x??0,s.y,s.z??0);
    for(let j=0;j<segments;j++){
      const a=i*segments+j,b=i*segments+(j+1)%segments;
      indices.push(center,top?b:a,top?a:b);
    }
  }
  return {positions,indices};
}

/** Smooth section interpolation, with radii clamped to avoid inverted surfaces. */
export function smoothSections(input:readonly Section[],steps=3):Section[]{
  const points=[...input].sort((a,b)=>a.y-b.y),out:Section[]=[];
  if(points.length<2||steps<1||!Number.isInteger(steps))throw Error('Invalid section interpolation');
  const value=(a:number,b:number,c:number,d:number,t:number)=>.5*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t);
  for(let i=0;i<points.length-1;i++)for(let j=0;j<steps;j++){
    const a=points[Math.max(0,i-1)],b=points[i],c=points[i+1],d=points[Math.min(points.length-1,i+2)],t=j/steps;
    out.push({y:b.y+(c.y-b.y)*t,rx:Math.max(.05,value(a.rx,b.rx,c.rx,d.rx,t)),rz:Math.max(.05,value(a.rz,b.rz,c.rz,d.rz,t)),
      x:value(a.x??0,b.x??0,c.x??0,d.x??0,t),z:value(a.z??0,b.z??0,c.z??0,d.z??0,t)});
  }
  return [...out,points.at(-1)!];
}

export const STUDY_DURATION=2;
export const BEND_KEYS=Object.freeze([{frame:0,value:0},{frame:15,value:0},{frame:30,value:-Math.PI/2},{frame:45,value:-Math.PI/2},{frame:60,value:0}]);
export function studyTime(value:number){return Number.isFinite(value)?Math.max(0,Math.min(STUDY_DURATION,value)):0;}

import {Animation,AnimationGroup,Color3,Mesh,MeshBuilder,PBRMaterial,TransformNode,Vector3,VertexData,type Scene,type Material} from '@babylonjs/core';
import {loftSurface,smoothSections,BEND_KEYS,type Section} from './meshGeometry';

export type Study={root:TransformNode;meshes:Mesh[];joints:Map<string,TransformNode>;rest:Map<TransformNode,Vector3>;clips:Map<string,AnimationGroup>};
export function surface(name:string,sections:readonly Section[],parent:TransformNode,material:Material,smooth=true,segments=24,square=1){
  const data=loftSurface(smooth?smoothSections(sections):sections,segments,square),normals:number[]=[];
  VertexData.ComputeNormals(data.positions,data.indices,normals,{useRightHandedSystem:true});
  const vertex=new VertexData();vertex.positions=data.positions;vertex.indices=data.indices;vertex.normals=normals;
  const mesh=new Mesh(name,parent.getScene());vertex.applyToMesh(mesh);mesh.sideOrientation=1;mesh.parent=parent;mesh.material=material;mesh.isPickable=true;
  return mesh;
}
export function workshopMaterials(scene:Scene){
  const make=(name:string,color:string,metallic:number,roughness:number)=>{const m=new PBRMaterial(name,scene);m.albedoColor=Color3.FromHexString(color);m.metallic=metallic;m.roughness=roughness;return m;};
  const light=make('Warm crystal','#b1e8dd',.25,.24);light.emissiveColor=Color3.FromHexString('#4b9d87').scale(.5);
  return {clay:make('Neutral anatomical clay','#c6b3a0',0,.78),modesty:make('Matte modesty layer','#637875',0,.95),
    stone:make('Carved limestone','#9caaa0',0,.88),darkStone:make('Recessed stone','#425b59',0,.9),
    brass:make('Brushed brass','#b69456',.72,.38),cloth:make('Woven cloth sample','#813c4d',0,.96),light};
}
export function anatomicalStudy(scene:Scene,m:ReturnType<typeof workshopMaterials>):Study{
  const root=new TransformNode('Anatomy study',scene),meshes:Mesh[]=[],joints=new Map<string,TransformNode>(),rest=new Map<TransformNode,Vector3>();
  const node=(name:string,parent:TransformNode,x:number,y:number,z=0)=>{const n=new TransformNode(name,scene);n.parent=parent;n.position.set(x,y,z);joints.set(name,n);return n;};
  const skin=(name:string,sections:Section[],parent=root,mat:Material=m.clay)=>{const mesh=surface(name,sections,parent,mat);meshes.push(mesh);return mesh;};
  skin('Pelvis and torso',[{y:40,rx:5.8,rz:3.5},{y:43,rx:9,rz:5},{y:46,rx:9.6,rz:5.1},{y:51,rx:7.5,rz:4.2},{y:55,rx:8.4,rz:4.6},{y:60,rx:10.5,rz:5.2},{y:63,rx:11,rz:4.5},{y:65,rx:10.2,rz:3.6},{y:67,rx:4,rz:2.9},{y:69,rx:3,rz:2.7}]);
  // A neutral close-fitting layer, not an outfit fitted over an unvalidated rig.
  skin('Modesty surface',[{y:40.4,rx:6.3,rz:3.9},{y:43.2,rx:9.16,rz:5.16},{y:46,rx:9.75,rz:5.23},{y:49,rx:8.25,rz:4.7},{y:51,rx:7.67,rz:4.35},{y:55,rx:8.57,rz:4.75},{y:60,rx:10.65,rz:5.35},{y:62,rx:10.9,rz:5.03}],root,m.modesty);
  const head=node('Neck',root,0,68);
  skin('Head',[{y:0,rx:2.6,rz:2.7,z:.4},{y:1.5,rx:3.3,rz:3.2,z:.6},{y:3.2,rx:4.5,rz:3.9,z:.5},{y:6,rx:5.1,rz:4.6},{y:8.8,rx:4.8,rz:4.5,z:-.3},{y:11,rx:3.6,rz:3.6,z:-.4},{y:12,rx:1.4,rz:1.6,z:-.4}],head);
  skin('Nose',[{y:3.5,rx:.65,rz:.6,z:4.3},{y:4.5,rx:1,rz:1,z:4.8},{y:6.6,rx:.45,rz:.45,z:4.4}],head);
  for(const side of [-1,1]){
    const ear=skin(`Ear ${side}`,[{y:3.8,rx:.5,rz:.6},{y:5.5,rx:.8,rz:1},{y:7,rx:.45,rz:.6}],head);ear.position.x=side*4.8;
    const shoulder=node(side>0?'Right shoulder':'Left shoulder',root,side*10.2,63.8);
    shoulder.rotation.z=side*Math.PI/4;
    skin(`Upper arm ${side}`,[{y:-14.5,rx:2.1,rz:2},{y:-11.5,rx:2.6,rz:2.5},{y:-6,rx:3.15,rz:3},{y:-2,rx:3.6,rz:3.3},{y:.7,rx:2.9,rz:2.7}],shoulder);
    const elbow=node(side>0?'Right elbow':'Left elbow',shoulder,0,-14);
    skin(`Forearm ${side}`,[{y:-13,rx:1.3,rz:1.35},{y:-11,rx:1.55,rz:1.55},{y:-5,rx:2.2,rz:2.15},{y:-1,rx:2.25,rz:2.05},{y:.6,rx:1.8,rz:1.8}],elbow);
    const wrist=node(side>0?'Right wrist':'Left wrist',elbow,0,-12.8);
    skin(`Palm ${side}`,[{y:-4.4,rx:1.7,rz:.68},{y:-2.5,rx:1.8,rz:.8},{y:-.4,rx:1.3,rz:1},{y:.4,rx:1.15,rz:1.05}],wrist);
    for(let f=0;f<4;f++){
      const finger=skin(`Finger ${side}:${f}`,[{y:-3.5+Math.abs(f-1)*.35,rx:.22,rz:.25},{y:-1.5,rx:.32,rz:.32},{y:0,rx:.33,rz:.36}],wrist);
      finger.position.set((f-1.5)*.93,-4,0);finger.rotation.z=(f-1.5)*.075;
    }
    const thumb=skin(`Thumb ${side}`,[{y:-2.7,rx:.2,rz:.25},{y:-1,rx:.45,rz:.4},{y:.2,rx:.5,rz:.5}],wrist);thumb.position.set(side*1.5,-1.3,.1);thumb.rotation.z=side*.65;
    const hip=node(side>0?'Right hip':'Left hip',root,side*5.8,42);
    skin(`Thigh ${side}`,[{y:-19,rx:2.5,rz:2.6},{y:-15,rx:3.2,rz:3.4},{y:-6,rx:4.35,rz:4.4},{y:0,rx:4.4,rz:4.5}],hip);
    const knee=node(side>0?'Right knee':'Left knee',hip,0,-18.5);
    skin(`Shin ${side}`,[{y:-19,rx:1.7,rz:1.65},{y:-16,rx:1.85,rz:1.9},{y:-9,rx:2.8,rz:3,z:-.5},{y:-4,rx:2.7,rz:2.7},{y:.5,rx:2.35,rz:2.4}],knee);
    const ankle=node(side>0?'Right ankle':'Left ankle',knee,0,-19.5);
    skin(`Foot ${side}`,[{y:-4,rx:2.1,rz:3.8,z:1.6},{y:-3.2,rx:2.5,rz:4.5,z:2.1},{y:-1,rx:2.3,rz:3.6,z:1.4},{y:.5,rx:1.65,rz:1.8}],ankle);
  }
  for(const n of joints.values())rest.set(n,n.rotation.clone());
  const clips=new Map<string,AnimationGroup>();
  for(const [label,joint,axis,sign] of [['Elbow bend','Right elbow','x',1],['Shoulder raise','Right shoulder','z',-1],['Knee bend','Right knee','x',-1]] as const){
    const target=joints.get(joint)!,group=new AnimationGroup(label,scene),track=new Animation(label,`rotation.${axis}`,30,Animation.ANIMATIONTYPE_FLOAT,Animation.ANIMATIONLOOPMODE_CYCLE);
    const base=rest.get(target)![axis];track.setKeys(BEND_KEYS.map(k=>({frame:k.frame,value:base+k.value*sign})));group.addTargetedAnimation(track,target);group.start(false);group.pause();clips.set(label,group);
  }
  return {root,meshes,joints,rest,clips};
}

export function sanctuaryStudy(scene:Scene,m:ReturnType<typeof workshopMaterials>){
  const root=new TransformNode('Sanctuary lantern study',scene),meshes:Mesh[]=[];
  const shape=(name:string,rings:Section[],mat:Material,square=.55,segments=16)=>{const mesh=surface(name,rings,root,mat,false,segments,square);meshes.push(mesh);return mesh;};
  shape('Chamfered foundation',[{y:0,rx:16,rz:16},{y:1,rx:18,rz:18},{y:3,rx:18,rz:18},{y:5,rx:15,rz:15}],m.darkStone);
  shape('Beveled stone course',[{y:5,rx:15,rz:15},{y:7,rx:16,rz:16},{y:9,rx:15,rz:15},{y:10,rx:12,rz:12}],m.stone);
  shape('Carved tapered shaft',[{y:10,rx:11.4,rz:11.4},{y:13,rx:11,rz:11},{y:33,rx:8.4,rz:8.4},{y:36,rx:10.5,rz:10.5},{y:39,rx:10.5,rz:10.5}],m.stone,.65);
  shape('Capital recess',[{y:39,rx:9.5,rz:9.5},{y:41,rx:12,rz:12},{y:43,rx:12,rz:12},{y:44,rx:10,rz:10}],m.darkStone);
  shape('Brass capital trim',[{y:40,rx:12.3,rz:12.3},{y:40.8,rx:12.3,rz:12.3}],m.brass);
  const crystal=shape('Cut crystal',[{y:43,rx:2,rz:2},{y:47,rx:5.3,rz:5.3},{y:56,rx:4.3,rz:4.3},{y:62,rx:.15,rz:.15}],m.light,1,6);
  for(let i=0;i<4;i++){
    const a=i*Math.PI/2+Math.PI/4;
    const rib=shape(`Stone pilaster ${i}`,[{y:10,rx:1.5,rz:1.4,z:11},{y:14,rx:1.3,rz:1.3,z:10.5},{y:33,rx:1.1,rz:1.1,z:8.6},{y:36,rx:1.5,rz:1.5,z:10}],m.darkStone,.7,12);rib.rotation.y=a;
    const fin=shape(`Brass lantern prong ${i}`,[{y:43,rx:1,rz:2,z:9},{y:47,rx:1,rz:1.6,z:8},{y:55,rx:.8,rz:1.2,z:7},{y:58,rx:.3,rz:.4,z:6}],m.brass,.6,12);fin.rotation.y=a;
  }
  return {root,meshes,crystal};
}

import {useEffect,useRef,useState} from 'react';
import {WorkshopScene,type WorkshopOptions,type WorkshopStats} from './WorkshopScene';
import {STUDY_DURATION} from './meshGeometry';
import './workshop.css';

const initial:WorkshopOptions={clip:'Rest pose',time:0,playing:false,speed:1,wireframe:false,joints:false,subject:'both',light:1};
