  const [options,setOptions]=useState<WorkshopOptions>(()=>({...initial,subject:innerWidth<650?'anatomy':'both'})),[stats,setStats]=useState<WorkshopStats|null>(null),[error,setError]=useState(''),[reference,setReference]=useState(true);
  const latest=useRef(options);latest.current=options;
  useEffect(()=>{
    let mounted=true,instance:WorkshopScene|undefined;
    try{
      instance=new WorkshopScene(canvas.current!,s=>{if(mounted)setStats(s);});studio.current=instance;instance.setOptions(latest.current);
      if(import.meta.env.DEV)(window as Window&{__visualWorkshop?:WorkshopScene}).__visualWorkshop=instance;
    }catch(e){setError(e instanceof Error?e.message:String(e));}
    return()=>{mounted=false;instance?.dispose();if(studio.current===instance)studio.current=null;
      const host=window as Window&{__visualWorkshop?:WorkshopScene};if(host.__visualWorkshop===instance)delete host.__visualWorkshop;};
  },[]);
  useEffect(()=>{studio.current?.setOptions(options);},[options]);
  const update=(patch:Partial<WorkshopOptions>)=>setOptions(o=>({...o,...patch}));
  const currentTime=()=>studio.current?.inspect().time??options.time;
  const step=(direction:number)=>update({playing:false,time:Math.max(0,Math.min(STUDY_DURATION,Math.round((currentTime()+direction/30)*30)/30))});
  const save=()=>{const blob=new Blob([JSON.stringify({schema:1,stage:'foundation-study-unqualified',options:{...options,time:currentTime()},inspection:studio.current?.inspect(),metrics:stats},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='babylon-workshop-inspection.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  return <div className="vw-shell">
    <header className="vw-header"><div><div className="vw-eyebrow">TEAMFIGHT / VISUAL PRODUCTION</div><h1>Babylon workshop <span>01</span></h1></div><div className="vw-header-actions"><span className="vw-status">{error?'Graphics unavailable':stats?.status??'Opening studio'}</span><a href="/">Back to game ↗</a></div></header>
    <main className={`vw-layout ${reference?'':'vw-without-reference'}`}>
      <aside className="vw-controls" aria-label="Model inspection controls">
        <section><div className="vw-section-label">INSPECTION SUBJECT</div><h2>Form before finish.</h2><p className="vw-muted">Fresh geometry, neutral materials, clear joints.</p>
          <label>Show<select aria-label="Inspection subject" value={options.subject} onChange={e=>update({subject:e.target.value as WorkshopOptions['subject']})}><option value="both">Anatomy + carved prop</option><option value="anatomy">Anatomy study</option><option value="prop">Carved lantern study</option></select></label>
        </section>
        <section><div className="vw-section-label">CAMERA</div><div className="vw-view-buttons">{['Front','Side','Back','Orbit','Match'].map(view=><button key={view} onClick={()=>studio.current?.view(view)}>{view}</button>)}</div><p className="vw-muted vw-small">Drag to orbit · right-drag to pan · scroll to zoom</p><p className="vw-muted vw-small">Match: 50° tilt, 2.8× spectator framing.</p></section>
        <section><div className="vw-section-label">SURFACE & STRUCTURE</div><label className="vw-toggle"><input type="checkbox" checked={options.wireframe} onChange={e=>update({wireframe:e.target.checked})}/>Wireframe</label><label className="vw-toggle"><input type="checkbox" checked={options.joints} onChange={e=>update({joints:e.target.checked})}/>Joint hierarchy</label><label className="vw-toggle"><input type="checkbox" checked={reference} onChange={e=>setReference(e.target.checked)}/>Show design reference</label>
          <label>Key light <output>{options.light.toFixed(1)}×</output><input aria-label="Key light" type="range" min="0.4" max="1.8" step="0.1" value={options.light} onChange={e=>update({light:Number(e.target.value)})}/></label>
        </section>
        <section><div className="vw-section-label">MATERIAL STUDIES</div><div className="vw-swatches">{[['Clay','#c6b3a0'],['Matte','#637875'],['Stone','#9caaa0'],['Brass','#b69456'],['Cloth','#813c4d']].map(([name,color])=><span key={name}><i style={{background:color}}/>{name}</span>)}</div></section>
        <section className="vw-stage-note"><strong>Foundation study</strong><p>New rest-pose anatomy and isolated joint tests. Mirelle’s final model, skin deformation, costume and combat motions come next.</p><button className="vw-export" onClick={save} disabled={!stats}>Export inspection</button></section>
      </aside>
      <section className="vw-stage" aria-label="3D modeling stage">
