        </div>
      </section>
      {reference&&<aside className="vw-reference" aria-label="Mirelle visual reference"><div className="vw-section-label">DESIGN REFERENCE</div><h2>Mirelle Vane</h2><span className="vw-reference-tag">REFERENCE ONLY</span><img src={`${import.meta.env.BASE_URL}art/avatar-drawings-v1/mirelle-vane.png`} alt="Mirelle Vane costume, silhouette and equipment reference"/><p className="vw-muted">Adult humanoid · atelier mage</p><p>The illustration guides later appearance work. The neutral base stays free of hair, clothing and equipment until its rig passes.</p><div className="vw-next"><span className="vw-section-label">NEXT GATE</span><strong>Base anatomy & deformation</strong><p>Controlled bends, shoulder clearance, hand separation and planted feet.</p></div></aside>}
    </main>
    <footer className="vw-metrics" aria-label="Rendering measurements"><span><b>{stats?.triangles.toLocaleString()??'—'}</b> study triangles</span><span><b>{stats?.meshes??'—'}</b> meshes</span><span><b>{stats?.materials??'—'}</b> materials</span><span><b>{stats?.drawCalls??'—'}</b> draw calls</span><span><b>{stats?.frameMs.toFixed(1)??'—'} ms</b> frame</span><span className="vw-metric-device" title={stats?.renderer}>{stats?.renderer??'Detecting renderer'}</span></footer>
  </div>;
}

