import {ArcRotateCamera,Camera,Color3,Color4,DirectionalLight,Engine,HemisphericLight,MeshBuilder,PBRMaterial,Scene,ShadowGenerator,Vector3,type LinesMesh,type Mesh} from '@babylonjs/core';
import {arenaGroundHeight} from '../arenaElevation';
import {studyTime,STUDY_DURATION} from './meshGeometry';
import {anatomicalStudy,sanctuaryStudy,workshopMaterials} from './studies';

export type WorkshopOptions={clip:string;time:number;playing:boolean;speed:number;wireframe:boolean;joints:boolean;subject:'both'|'anatomy'|'prop';light:number};
export type WorkshopStats={triangles:number;meshes:number;materials:number;drawCalls:number;frameMs:number;fps:number;renderer:string;ground:number;time:number;status:string};
export class WorkshopScene{
  private engine:Engine;private scene!:Scene;private camera:ArcRotateCamera;private observer:ResizeObserver;
  private anatomy:ReturnType<typeof anatomicalStudy>;private prop:ReturnType<typeof sanctuaryStudy>;
  private materials:ReturnType<typeof workshopMaterials>;private sun:DirectionalLight;
  private guides:Mesh[]=[];private bones:LinesMesh;private halfH=61;private elapsed=0;private lastStats=0;private disposed=false;private lost=false;
  private options:WorkshopOptions={clip:'Rest pose',time:0,playing:false,speed:1,wireframe:false,joints:false,subject:'both',light:1};
  private ground=arenaGroundHeight(1300,720);
  private wheel=(e:WheelEvent)=>{e.preventDefault();this.halfH=Math.max(28,Math.min(300,this.halfH*Math.exp(e.deltaY*.001)));this.resize();};
  private visibility=()=>{this.engine.getDeltaTime();};
  constructor(private canvas:HTMLCanvasElement,private onStats:(stats:WorkshopStats)=>void){
    this.engine=new Engine(canvas,true,{stencil:true,preserveDrawingBuffer:false});
    try{
      this.engine.setHardwareScalingLevel(1/Math.min(1.5,devicePixelRatio||1));
      this.scene=new Scene(this.engine);this.scene.useRightHandedSystem=true;this.scene.clearColor=new Color4(.065,.09,.105,1);
      this.scene.imageProcessingConfiguration.toneMappingEnabled=true;this.scene.imageProcessingConfiguration.exposure=1.25;
      this.camera=new ArcRotateCamera('Inspection camera',Math.PI/2,Math.PI/2-50*Math.PI/180,180,new Vector3(0,this.ground+39,0),this.scene);
      this.camera.mode=Camera.ORTHOGRAPHIC_CAMERA;this.camera.minZ=.1;this.camera.maxZ=1500;this.camera.lowerBetaLimit=.08;this.camera.upperBetaLimit=Math.PI/2+.15;
      this.camera.panningSensibility=80;this.camera.attachControl(canvas,true);this.camera.inputs.removeByType('ArcRotateCameraMouseWheelInput');
      const fill=new HemisphericLight('Soft sky',new Vector3(.2,1,.3),this.scene);fill.intensity=.65;fill.groundColor=Color3.FromHexString('#687d74');
      this.sun=new DirectionalLight('Studio key',new Vector3(-.6,-1,-.5),this.scene);this.sun.position.set(90,this.ground+150,90);this.sun.intensity=2.7;
      this.materials=workshopMaterials(this.scene);this.anatomy=anatomicalStudy(this.scene,this.materials);this.prop=sanctuaryStudy(this.scene,this.materials);
      this.anatomy.root.position.set(-28,this.ground,0);this.prop.root.position.set(55,this.ground,0);
      const floor=MeshBuilder.CreateGround('Inspection ground',{width:800,height:800},this.scene);floor.position.y=this.ground-.05;
      const floorMat=new PBRMaterial('Ground matte',this.scene);floorMat.albedoColor=Color3.FromHexString('#172225');floorMat.metallic=0;floorMat.roughness=1;floor.material=floorMat;floor.receiveShadows=true;
      const shadows=new ShadowGenerator(1024,this.sun);shadows.useBlurExponentialShadowMap=true;shadows.blurKernel=16;shadows.bias=.0005;shadows.normalBias=.04;shadows.setDarkness(.3);
      for(const mesh of [...this.anatomy.meshes,...this.prop.meshes]){mesh.receiveShadows=true;shadows.addShadowCaster(mesh,false);}
      const grid:Vector3[][]=[];for(let i=-200;i<=200;i+=10){grid.push([new Vector3(i,this.ground+.01,-200),new Vector3(i,this.ground+.01,200)],[new Vector3(-200,this.ground+.01,i),new Vector3(200,this.ground+.01,i)]);}
      const lines=MeshBuilder.CreateLineSystem('10-unit grid',{lines:grid},this.scene);lines.color=new Color3(.44,.59,.59);lines.alpha=.13;lines.isPickable=false;
      const guideMaterial=new PBRMaterial('Joint guides',this.scene);guideMaterial.albedoColor=Color3.FromHexString('#e2b65e');guideMaterial.emissiveColor=Color3.FromHexString('#c99d43');guideMaterial.unlit=true;
      for(const [name,joint] of this.anatomy.joints){const dot=MeshBuilder.CreateSphere(`Joint: ${name}`,{diameter:1.35,segments:6},this.scene);dot.parent=joint;dot.material=guideMaterial;dot.isPickable=false;dot.setEnabled(false);this.guides.push(dot);}
      this.bones=MeshBuilder.CreateLineSystem('Joint hierarchy',{lines:this.boneLines(),updatable:true},this.scene);this.bones.color=Color3.FromHexString('#efc66f');this.bones.isPickable=false;this.bones.setEnabled(false);
      this.observer=new ResizeObserver(()=>{if(!this.disposed)this.resize();});this.observer.observe(canvas);
      canvas.addEventListener('wheel',this.wheel,{passive:false});document.addEventListener('visibilitychange',this.visibility);
      this.engine.onContextLostObservable.add(()=>{this.lost=true;this.report('Graphics paused');});
      this.engine.onContextRestoredObservable.add(()=>{this.lost=false;this.report('Ready');});
      this.resize();this.view('Orbit');this.engine.runRenderLoop(()=>this.draw());this.report('Ready');
    }catch(error){this.scene?.dispose();this.engine.dispose();throw error;}
  }
  private boneLines(){return [...this.anatomy.joints.values()].map(j=>{j.computeWorldMatrix(true);const parent=j.parent;parent?.computeWorldMatrix(true);return [j.getAbsolutePosition().clone(),parent&&'getAbsolutePosition' in parent?(parent as typeof j).getAbsolutePosition().clone():j.getAbsolutePosition().clone()];});}
  private resize(){this.engine.resize();const aspect=this.canvas.clientWidth/Math.max(1,this.canvas.clientHeight);this.camera.orthoLeft=-this.halfH*aspect;this.camera.orthoRight=this.halfH*aspect;this.camera.orthoTop=this.halfH;this.camera.orthoBottom=-this.halfH;}
  setOptions(options:WorkshopOptions){
    if(this.disposed)return;
    const subjectChanged=options.subject!==this.options.subject;
    if(!options.playing||options.time!==this.options.time)this.elapsed=studyTime(options.time);
    this.options={...options};
    for(const mat of Object.values(this.materials))mat.wireframe=options.wireframe;
    this.anatomy.root.setEnabled(options.subject!=='prop');this.prop.root.setEnabled(options.subject!=='anatomy');
    for(const dot of this.guides)dot.setEnabled(options.joints);
    this.bones.setEnabled(options.joints&&options.subject!=='prop');this.sun.intensity=2.7*options.light;
    if(subjectChanged)this.view('Orbit');
  }
  view(preset:string){
    this.camera.target.set(this.options.subject==='anatomy'?-28:this.options.subject==='prop'?55:0,this.ground+39,0);
    this.camera.alpha=preset==='Side'?0:preset==='Back'?-Math.PI/2:Math.PI/2;
    this.camera.beta=preset==='Match'?Math.PI/2-50*Math.PI/180:preset==='Orbit'?.95:Math.PI/2-.02;
    const aspect=this.canvas.clientWidth/Math.max(1,this.canvas.clientHeight);
    this.halfH=preset==='Match'?(2600+96)/(2*2.8*(16/9)):Math.max(61,(this.options.subject==='both'?86:42)/aspect);
    this.camera.radius=180;this.resize();
  }
  private pose(){
    for(const group of this.anatomy.clips.values())group.setWeightForAllAnimatables(0);
    for(const [node,rotation] of this.anatomy.rest)node.rotation.copyFrom(rotation);
    const clip=this.anatomy.clips.get(this.options.clip);clip?.setWeightForAllAnimatables(1);clip?.goToFrame(this.elapsed*30,false);
    if(this.options.joints)MeshBuilder.CreateLineSystem('',{lines:this.boneLines(),instance:this.bones},this.scene);
  }
  private draw(){
    if(this.disposed||this.lost||document.hidden)return;
    if(this.options.playing&&this.options.clip!=='Rest pose')this.elapsed=(this.elapsed+Math.min(.05,this.engine.getDeltaTime()/1000)*this.options.speed)%STUDY_DURATION;
    this.pose();this.scene.render();
    if(performance.now()-this.lastStats>250){this.lastStats=performance.now();this.report('Ready');}
  }
  private report(status:string){
    const meshes=[...this.anatomy.meshes,...this.prop.meshes].filter(m=>m.isEnabled());
    this.onStats({triangles:meshes.reduce((n,m)=>n+m.getTotalIndices()/3,0),meshes:meshes.length,materials:new Set(meshes.map(m=>m.material)).size,
      drawCalls:this.engine._drawCalls.current,frameMs:this.engine.getDeltaTime(),fps:this.engine.getFps(),renderer:this.engine.getGlInfo().renderer,ground:this.ground,time:this.elapsed,status});
  }
  inspect(){this.pose();return {time:this.elapsed,clip:this.options.clip,joints:Object.fromEntries([...this.anatomy.joints].map(([name,n])=>[name,{x:n.rotation.x,y:n.rotation.y,z:n.rotation.z}])),
    meshes:this.anatomy.meshes.length+this.prop.meshes.length,triangles:[...this.anatomy.meshes,...this.prop.meshes].reduce((n,m)=>n+m.getTotalIndices()/3,0),
    imageTextures:this.scene.textures.filter(t=>/\.png|\.jpg|\.webp/.test(String('url' in t?t.url:t.name))).length,ground:this.ground,disposed:this.disposed,halfHeight:this.halfH};}
  dispose(){if(this.disposed)return;this.disposed=true;this.engine.stopRenderLoop();this.observer?.disconnect();this.canvas.removeEventListener('wheel',this.wheel);document.removeEventListener('visibilitychange',this.visibility);this.scene.dispose();this.engine.dispose();}
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {loftSurface,smoothSections,studyTime} from './visual-workshop/meshGeometry.ts';

test('custom workshop surfaces are closed, outward wound and finite',()=>{
  for(const square of [1,.55]){
    const mesh=loftSurface(smoothSections([{y:0,rx:4,rz:3},{y:4,rx:5,rz:2},{y:8,rx:2,rz:1}]),24,square);
    assert.ok(mesh.positions.every(Number.isFinite));
    const edges=new Map();let volume=0;
    for(let i=0;i<mesh.indices.length;i+=3){
      const tri=mesh.indices.slice(i,i+3);assert.equal(new Set(tri).size,3);
      for(let j=0;j<3;j++){const a=tri[j],b=tri[(j+1)%3],key=[a,b].sort((x,y)=>x-y).join(':');edges.set(key,(edges.get(key)??0)+1);}
      const [a,b,c]=tri.map(v=>mesh.positions.slice(v*3,v*3+3));
      volume+=(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6;
    }
    assert.ok([...edges.values()].every(n=>n===2),'each edge is shared by exactly two faces');assert.ok(volume>0,'surface normals face outward');
  }
});
test('bad loft sections are rejected and inspection time is bounded',()=>{
  assert.throws(()=>loftSurface([{y:0,rx:1,rz:1},{y:0,rx:2,rz:1}]));
  assert.throws(()=>loftSurface([{y:0,rx:NaN,rz:1},{y:1,rx:2,rz:1}]));
  assert.ok(loftSurface([{y:0,rx:2,rz:2},{y:4,rx:1,rz:1}],6).indices.length>0,'six-sided crystals are valid closed geometry');
  assert.equal(studyTime(-1),0);assert.equal(studyTime(Infinity),0);assert.equal(studyTime(4),2);assert.equal(studyTime(1/30),1/30);
});

